using System.Text.Json;
using Windows.Win32;
using Windows.Win32.Foundation;
using Windows.Win32.Graphics.Direct3D;
using Windows.Win32.Graphics.Direct3D12;
using Windows.Win32.Graphics.Dxgi;
using Windows.Win32.System.Com;

namespace BunOs.Windows.Native;

/// <summary>
/// <c>graphics.adapters</c>: DXGI 1.6 adapter enumeration by GPU preference and, per adapter, a Direct3D 12 device with
/// its feature tiers. Raw COM vtables generated by CsWin32 (no runtime marshalling).
/// </summary>
internal static unsafe class Graphics
{
    private static readonly D3D_FEATURE_LEVEL[] s_levels =
    [
        D3D_FEATURE_LEVEL.D3D_FEATURE_LEVEL_12_2,
        D3D_FEATURE_LEVEL.D3D_FEATURE_LEVEL_12_1,
        D3D_FEATURE_LEVEL.D3D_FEATURE_LEVEL_12_0,
        D3D_FEATURE_LEVEL.D3D_FEATURE_LEVEL_11_1,
        D3D_FEATURE_LEVEL.D3D_FEATURE_LEVEL_11_0,
    ];

    public static void Adapters(JsonElement args, Utf8JsonWriter w, Action<string>? progress)
    {
        var preference = args.Str("preference") switch
        {
            "minimum-power" => DXGI_GPU_PREFERENCE.DXGI_GPU_PREFERENCE_MINIMUM_POWER,
            "unspecified" => DXGI_GPU_PREFERENCE.DXGI_GPU_PREFERENCE_UNSPECIFIED,
            _ => DXGI_GPU_PREFERENCE.DXGI_GPU_PREFERENCE_HIGH_PERFORMANCE,
        };
        var withDevice = args.Bool("device", true);

        void* raw;
        var factoryIid = IDXGIFactory6.IID_Guid;
        PInvoke.CreateDXGIFactory2(0, &factoryIid, &raw).ThrowOnFailure();
        var factory = (IDXGIFactory6*)raw;
        try
        {
            w.WriteStartArray();
            var adapterIid = IDXGIAdapter4.IID_Guid;
            for (uint index = 0; ; index++)
            {
                void* adapterRaw;
                var hr = factory->EnumAdapterByGpuPreference(index, preference, &adapterIid, &adapterRaw);
                if (hr == HRESULT.DXGI_ERROR_NOT_FOUND) break;
                hr.ThrowOnFailure();
                var adapter = (IDXGIAdapter4*)adapterRaw;
                try
                {
                    WriteAdapter(w, index, adapter, withDevice);
                }
                finally
                {
                    adapter->Release();
                }
            }
            w.WriteEndArray();
        }
        finally
        {
            factory->Release();
        }
    }

    private static void WriteAdapter(Utf8JsonWriter w, uint index, IDXGIAdapter4* adapter, bool withDevice)
    {
        DXGI_ADAPTER_DESC3 desc;
        adapter->GetDesc3(&desc).ThrowOnFailure();
        w.WriteStartObject();
        w.WriteNumber("index", index);
        w.WriteString("name", desc.Description.ToString());
        w.WriteString("vendorId", $"0x{desc.VendorId:X4}");
        w.WriteString("deviceId", $"0x{desc.DeviceId:X4}");
        w.WriteString("subSysId", $"0x{desc.SubSysId:X8}");
        w.WriteNumber("revision", desc.Revision);
        w.WriteNumber("dedicatedVideoMemory", (ulong)desc.DedicatedVideoMemory);
        w.WriteNumber("dedicatedSystemMemory", (ulong)desc.DedicatedSystemMemory);
        w.WriteNumber("sharedSystemMemory", (ulong)desc.SharedSystemMemory);
        w.WriteString("luid", $"{desc.AdapterLuid.HighPart:X8}:{desc.AdapterLuid.LowPart:X8}");
        w.WriteBoolean("software", (desc.Flags & DXGI_ADAPTER_FLAG3.DXGI_ADAPTER_FLAG3_SOFTWARE) != 0);
        w.WriteString("graphicsPreemption", desc.GraphicsPreemptionGranularity.ToString());
        w.WriteString("computePreemption", desc.ComputePreemptionGranularity.ToString());
        if (withDevice) WriteDevice(w, adapter);
        w.WriteEndObject();
    }

    private static void WriteDevice(Utf8JsonWriter w, IDXGIAdapter4* adapter)
    {
        void* raw;
        var deviceIid = ID3D12Device.IID_Guid;
        var hr = PInvoke.D3D12CreateDevice((IUnknown*)adapter, D3D_FEATURE_LEVEL.D3D_FEATURE_LEVEL_11_0, &deviceIid, &raw);
        if (hr.Failed)
        {
            w.WriteStartObject("d3d12");
            w.WriteBoolean("supported", false);
            w.WriteString("hresult", $"0x{hr.Value:X8}");
            w.WriteEndObject();
            return;
        }
        var device = (ID3D12Device*)raw;
        try
        {
            w.WriteStartObject("d3d12");
            w.WriteBoolean("supported", true);

            fixed (D3D_FEATURE_LEVEL* levels = s_levels)
            {
                var data = new D3D12_FEATURE_DATA_FEATURE_LEVELS
                {
                    NumFeatureLevels = (uint)s_levels.Length,
                    pFeatureLevelsRequested = levels,
                };
                if (device->CheckFeatureSupport(D3D12_FEATURE.D3D12_FEATURE_FEATURE_LEVELS, &data, (uint)sizeof(D3D12_FEATURE_DATA_FEATURE_LEVELS)).Succeeded)
                    w.WriteString("maxFeatureLevel", Level(data.MaxSupportedFeatureLevel));
            }

            // Highest shader model: ask for the newest the runtime may know and step down on E_INVALIDARG.
            for (var model = 0x6A; model >= 0x60; model--)
            {
                var sm = new D3D12_FEATURE_DATA_SHADER_MODEL { HighestShaderModel = (D3D_SHADER_MODEL)model };
                if (device->CheckFeatureSupport(D3D12_FEATURE.D3D12_FEATURE_SHADER_MODEL, &sm, (uint)sizeof(D3D12_FEATURE_DATA_SHADER_MODEL)).Succeeded)
                {
                    var m = (int)sm.HighestShaderModel;
                    w.WriteString("shaderModel", $"{m >> 4}.{m & 0xF}");
                    break;
                }
            }

            D3D12_FEATURE_DATA_D3D12_OPTIONS o;
            if (device->CheckFeatureSupport(D3D12_FEATURE.D3D12_FEATURE_D3D12_OPTIONS, &o, (uint)sizeof(D3D12_FEATURE_DATA_D3D12_OPTIONS)).Succeeded)
            {
                w.WriteString("resourceBindingTier", o.ResourceBindingTier.ToString());
                w.WriteString("tiledResourcesTier", o.TiledResourcesTier.ToString());
                w.WriteString("conservativeRasterizationTier", o.ConservativeRasterizationTier.ToString());
            }
            D3D12_FEATURE_DATA_D3D12_OPTIONS1 o1;
            if (device->CheckFeatureSupport(D3D12_FEATURE.D3D12_FEATURE_D3D12_OPTIONS1, &o1, (uint)sizeof(D3D12_FEATURE_DATA_D3D12_OPTIONS1)).Succeeded)
            {
                w.WriteBoolean("waveOps", o1.WaveOps);
                w.WriteNumber("waveLaneCountMin", o1.WaveLaneCountMin);
                w.WriteNumber("waveLaneCountMax", o1.WaveLaneCountMax);
            }
            D3D12_FEATURE_DATA_D3D12_OPTIONS5 o5;
            if (device->CheckFeatureSupport(D3D12_FEATURE.D3D12_FEATURE_D3D12_OPTIONS5, &o5, (uint)sizeof(D3D12_FEATURE_DATA_D3D12_OPTIONS5)).Succeeded)
                w.WriteString("raytracingTier", o5.RaytracingTier.ToString());
            D3D12_FEATURE_DATA_D3D12_OPTIONS7 o7;
            if (device->CheckFeatureSupport(D3D12_FEATURE.D3D12_FEATURE_D3D12_OPTIONS7, &o7, (uint)sizeof(D3D12_FEATURE_DATA_D3D12_OPTIONS7)).Succeeded)
            {
                w.WriteString("meshShaderTier", o7.MeshShaderTier.ToString());
                w.WriteString("samplerFeedbackTier", o7.SamplerFeedbackTier.ToString());
            }
            var arch = new D3D12_FEATURE_DATA_ARCHITECTURE1 { NodeIndex = 0 };
            if (device->CheckFeatureSupport(D3D12_FEATURE.D3D12_FEATURE_ARCHITECTURE1, &arch, (uint)sizeof(D3D12_FEATURE_DATA_ARCHITECTURE1)).Succeeded)
            {
                w.WriteBoolean("uma", arch.UMA);
                w.WriteBoolean("cacheCoherentUma", arch.CacheCoherentUMA);
                w.WriteBoolean("isolatedMmu", arch.IsolatedMMU);
            }
            w.WriteEndObject();
        }
        finally
        {
            device->Release();
        }
    }

    private static string Level(D3D_FEATURE_LEVEL level)
    {
        var value = (int)level;
        return $"{value >> 12}_{(value >> 8) & 0xF}";
    }
}
